# Clean up the output construction

def construct_output():
    output = []
    for r in range(28):
        row = [6] * 18
        row[6] = 2  # 2s at col 6

        # Cross parameters (matching demo pattern scaled up)
        cross_start_col = 9  # 1 col after 2's col
        cross_width = 4       # 4 columns wide (matching 9-block width)
        cross_center_col = cross_start_col + cross_width // 2  # 11 (center of 9-12)
        cross_start_row = 1   # Top row where cross starts
        cross_end_row = 19    # Bottom row where vertical extension stops
        center_row = 7        # Middle row for horizontal line

        if cross_start_row <= r <= cross_end_row:
            # In vertical span
            if r == center_row:
                # Horizontal line: left portion = 6s, right portion = 8s
                # Left 3 cols = 6, right 1 col = 8
                for c in range(cross_start_col, cross_start_col + cross_width):
                    if c == cross_start_col + cross_width - 1:
                        row[c] = 8
                    else:
                        row[c] = 6
            else:
                # Vertical line only
                if r <= 13:
                    row[cross_center_col] = 6
                else:
                    row[cross_center_col] = 8

        output.append(row)
    return output

output = construct_output()
print("Output grid (first 16 rows):")
for i in range(16):
    print(f"{i:2d}: {' '.join(map(str, output[i]))}")
print("...")
for i in range(16, 28):
    print(f"{i:2d}: {' '.join(map(str, output[i]))}")

